-- Phase 2 (Stream B, F2) — channel blueprint storage + niche filter columns.
--
-- Forward-only, non-destructive: ALTER TABLE ... ADD COLUMN IF NOT EXISTS only.
-- niches.blueprint holds the deterministic channel blueprint generated by
-- generateBlueprint() (rule-based, no LLM) as JSONB.
-- min_subs / max_subs / active_only / require_recent_activity persist the F1
-- niche filter bar; scoreNiche() honors them when recomputing scores.

ALTER TABLE public.niches
  ADD COLUMN IF NOT EXISTS blueprint jsonb NOT NULL DEFAULT '{}'::jsonb;

ALTER TABLE public.niches
  ADD COLUMN IF NOT EXISTS min_subs integer;

ALTER TABLE public.niches
  ADD COLUMN IF NOT EXISTS max_subs integer;

ALTER TABLE public.niches
  ADD COLUMN IF NOT EXISTS active_only boolean NOT NULL DEFAULT false;

ALTER TABLE public.niches
  ADD COLUMN IF NOT EXISTS require_recent_activity boolean NOT NULL DEFAULT false;

COMMENT ON COLUMN public.niches.blueprint IS
  'Phase 2 (F2): deterministic channel blueprint (positioning, content pillars, formats, cadence) generated from niche data + tracked-channel medians. Rule-based, no LLM.';

COMMENT ON COLUMN public.niches.min_subs IS
  'Phase 2 (F1): minimum subscriber count for channels scored in this niche. NULL = no lower bound.';

COMMENT ON COLUMN public.niches.max_subs IS
  'Phase 2 (F1): maximum subscriber count for channels scored in this niche. NULL = no upper bound.';

COMMENT ON COLUMN public.niches.active_only IS
  'Phase 2 (F1): when true, scoreNiche only considers channels with a snapshot in the last 14 days.';

COMMENT ON COLUMN public.niches.require_recent_activity IS
  'Phase 2 (F1): when true, scoreNiche only considers channels with a video published in the last 30 days.';
